def site_identifier(link_str):
  """
  link_str: link_str of a website to split from "/" and "."
  return: site identifier from the link_str
  """
  parts_list = ([segment.split(".") for segment in link_str.split("/")])
  for segment in parts_list:
    core_tokens = ([segment[idx] for idx in range(len(segment)) if segment[idx] != "www" and segment[idx] != "http:" and segment[idx] != "https:" and segment[idx] != ""])
    if core_tokens != []:
      return core_tokens[0]

