            input_info += "&{}".format(idx)
        elif grp == "integer":
            input_info += "${}:{}".format(idx, _to_type_info(int_vals[idx]))
        elif grp == "real":
            input_info += "${}:{}".format(idx, _to_type_info(real_vals[idx]))
        if i < len(groups_idx) - 1:
            input_info += " "
    return input_info

