def range_overlap(lowA, highA, lowB, highB):
    if (lowB >= lowA and lowB <= highA):
        if highB < highA:
            return highB - lowB
        else:
            return highA - lowB
    elif (lowA >= lowB and lowA <= highB):
        if highA < highB:
            return highA - lowA
        else:
            return highB - lowA
    return 0
